def monotonic(l):
    """
    Works for both list of numbers and strings.

    For list of numbers:
      - Return (True, sum) if elements are strictly monotonic increasing or decreasing (no duplicates)
      - Return False otherwise

    For strings:
      - Return (True, string) if characters are strictly monotonic alphabetical or reverse alphabetical (no duplicates)
      - Return False otherwise

    No loops or built-in sorting methods are used.
    """
    # Helper functions using recursion

    def has_duplicates(seq, idx=0):
        if idx == len(seq):
            return False
        # Check if seq[idx] appears later in the sequence
        if seq[idx] in seq[idx+1:]:
            return True
        return has_duplicates(seq, idx+1)

    def is_strictly_increasing(seq, idx=0):
        if idx == len(seq) - 1:
            return True
        if seq[idx] >= seq[idx+1]:
            return False
        return is_strictly_increasing(seq, idx+1)

    def is_strictly_decreasing(seq, idx=0):
        if idx == len(seq) - 1:
            return True
        if seq[idx] <= seq[idx+1]:
            return False
        return is_strictly_decreasing(seq, idx+1)

    def sum_list(seq, idx=0):
        if idx == len(seq):
            return 0
        return seq[idx] + sum_list(seq, idx+1)

    def sum_string(seq, idx=0):
        if idx == len(seq):
            return ""
        return seq[idx] + sum_string(seq, idx+1)

    # Main logic
    if not l:
        # Empty list or string: consider monotonic, sum is 0 or ""
        if isinstance(l, str):
            return True, ""
        else:
            return True, 0

    if has_duplicates(l):
        return False

    if is_strictly_increasing(l) or is_strictly_decreasing(l):
        if isinstance(l, str):
            s = sum_string(l)
            return True, s
        else:
            s = sum_list(l)
            return True, s
    else:
        return False


