def max_fill(grid, capacity):
    import math

    # Calculate total units of water in each well (row) using recursion
    def sum_row(row):
        if not row:
            return 0
        return row[0] + sum_row(row[1:])

    def sums(grid):
        if not grid:
            return []
        return [sum_row(grid[0])] + sums(grid[1:])

    # Sort the sums without changing the order of wells with same amount of water (stable sort)
    # We'll implement a merge sort recursively
    def merge_sort(arr):
        if len(arr) <= 1:
            return arr
        mid = len(arr) // 2
        left = merge_sort(arr[:mid])
        right = merge_sort(arr[mid:])

        def merge(l, r):
            if not l:
                return r
            if not r:
                return l
            if l[0][0] < r[0][0]:
                return [l[0]] + merge(l[1:], r)
            elif l[0][0] > r[0][0]:
                return [r[0]] + merge(l, r[1:])
            else:
                # equal values: keep original order, so take from left first
                return [l[0]] + merge(l[1:], r)

        return merge(left, right)

    # Get sums with their original indices to restore order after sorting
    sums_with_idx = [(s, i) for i, s in enumerate(sums(grid))]
    sorted_sums_with_idx = merge_sort(sums_with_idx)

    # Extract only sums (sorted) preserving original order among equals
    sorted_sums = [x[0] for x in sorted_sums_with_idx]

    # Calculate the number of times to lower buckets for each well (ceil division)
    def times_needed(water):
        if water == 0:
            return 0
        # Use recursion to implement ceil division: (water + capacity -1)//capacity
        # Without loops, simulate division by repeated subtraction recursively
        def div_ceil(n, d):
            if n <= 0:
                return 0
            if n <= d:
                return 1
            return 1 + div_ceil(n - d, d)
        return div_ceil(water, capacity)

    def total_times(arr):
        if not arr:
            return 0
        return times_needed(arr[0]) + total_times(arr[1:])

    return str(total_times(sorted_sums))

