def below_zero(operations):
    """
    Processes a list of operations given as strings ("deposit X" or "withdraw X").
    Returns True if at any point the balance goes below zero, otherwise False.

    Args:
    operations (list of str): List of operations, e.g. ["deposit 100", "withdraw 50"]

    Returns:
    bool: True if balance goes below zero at any point, False otherwise.
    """
    balance = 0
    for op in operations:
        parts = op.split()
        if len(parts) != 2:
            raise ValueError(f"Invalid operation format: '{op}'")

        action, amount_str = parts
        try:
            amount = int(amount_str)
        except ValueError:
            raise ValueError(f"Amount must be an integer in operation: '{op}'")

        if action == "deposit":
            balance += amount
        elif action == "withdraw":
            balance -= amount
        else:
            raise ValueError(f"Unknown operation '{action}' in '{op}'")

        if balance < 0:
            return True

    return False


# Example usage:
