def parse_nested_parens(group):
    """
    Given a string composed only of '(' and ')', returns the maximum nesting depth.
    Raises ValueError if the string contains invalid characters or is not balanced.
    """
    if not group:
        return 0  # empty group has zero depth

    max_depth = 0
    current_depth = 0

    for i, ch in enumerate(group):
        if ch == '(':
            current_depth += 1
            if current_depth > max_depth:
                max_depth = current_depth
        elif ch == ')':
            current_depth -= 1
            if current_depth < 0:
                raise ValueError(f"Unbalanced parentheses: too many closing ')' at position {i} in group '{group}'")
        else:
            raise ValueError(f"Invalid character '{ch}' found in group '{group}'")

    if current_depth != 0:
        raise ValueError(f"Unbalanced parentheses: too many opening '(' in group '{group}'")

    return max_depth


def process_paren_groups(text):
    """
    The input to this routine is a piece of data composed of several groups of parentheses separated by whitespace.
    For each group, return an indication of the deepest nesting level present.
    E.g. (()()) has two levels while ((())) has three.

    >>> process_paren_groups('(()()) ((())) () ((())()())')
    [2, 3, 1, 3]
    """
    groups = text.split()
    depths = []
    for group in groups:
        # Validate group contains only parentheses and is balanced, then get max depth
        depth = parse_nested_parens(group)
        depths.append(depth)
    return depths


