def tuple_to_set(data):
    """
    Convert the input which can be:
      - a single tuple
      - a tuple of tuples
      - a list of tuples
    into a set of frozensets, converting any inner tuples into frozensets.

    Examples:
    - (1, 2, 3) -> {frozenset({1,2,3})}
    - ((1, 2), (3, 4)) -> {frozenset({1,2}), frozenset({3,4})}
    - [(1, 2), (3, 4)] -> {frozenset({1,2}), frozenset({3,4})}

    """
    def tuple_to_frozenset(t):
        # Convert elements inside the tuple to frozenset if they are tuples
        converted = []
        for elem in t:
            if isinstance(elem, tuple):
                # Recursively convert inner tuple to frozenset
                converted.append(tuple_to_frozenset(elem))
            else:
                converted.append(elem)
        return frozenset(converted)

    # Determine if data is a single tuple or iterable of tuples
    if isinstance(data, tuple):
