def solution(a, b, n):
    """
    Find the first nonnegative integer solution (x, y) for the equation:
        a*x + b*y = n
    by increasing x from 0 upwards.

    Parameters:
        a (int): coefficient of x
        b (int): coefficient of y
        n (int): target value

    Returns:
        tuple: (x, y) the first nonnegative integer solution found, or None if no solution exists.
    """
    if a == 0 and b == 0:
        # If both coefficients are zero, equation is 0 = n
        return (0, 0) if n == 0 else None

    if a == 0:
        # Then b*y = n, y must be n/b if integer and nonnegative
        if b != 0 and n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return None

    if b == 0:
        # Then a*x = n, x must be n/a if integer and nonnegative
        if a != 0 and n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return None

    x = 0
    while a * x <= n:
        remainder = n - a * x
        if remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return (x, y)
        x += 1

    return None


