    print("First even number:", first_even(sample_list))  # Output: 8

def remove_column(data, key_to_remove):
    """
    Recursively removes all occurrences of key_to_remove from dictionaries inside nested data structures.

    Args:
        data: The nested data structure (can be dict, list, or other).
        key_to_remove: The key to remove from any dictionary found within data.

    Returns:
        The cleaned data structure with the specified key removed from all dictionaries.
    """
    if isinstance(data, dict):
        # Create a new dict without the key_to_remove
        return {k: remove_column(v, key_to_remove) for k, v in data.items() if k != key_to_remove}
    elif isinstance(data, list):
        # Recursively apply to each element in the list
        return [remove_column(item, key_to_remove) for item in data]
    else:
        # For other data types, just return as is
        return data


# Example usage:
if __name__ == "__main__":
    nested = {
        "a": 1,
        "remove_me": "bye",
        "b": {
            "remove_me": 2,
            "c": [
                {"remove_me": 3, "d": 4},
                {"e": 5}
            ]
        }
    }

    cleaned = remove_column(nested, "remove_me")
    print(cleaned)
    # Expected output:
    # {'a': 1, 'b': {'c': [{'d': 4}, {'e': 5}]}}

def check_subset(set1, set2):
    """
    Check if set1 is a subset of set2.

    Args:
        set1 (iterable): The first set or iterable.
        set2 (iterable): The second set or iterable.

    Returns:
        bool: True if set1 is a subset of set2, False otherwise.
    """
    return set(set1).issubset(set(set2))


# Example usage:
if __name__ == "__main__":
    a = {1, 2, 3}
    b = {1, 2, 3, 4, 5}
    c = {1, 2, 6}

    print(check_subset(a, b))  # True
    print(check_subset(c, b))  # False

