if __name__ == "__main__":
    permute_string("aab")

def drop_empty(d):
    """
    Recursively remove empty items from a dictionary.
    Empty items are considered:
      - None
      - empty string ''
      - empty list []
      - empty dict {}
      - empty tuple ()
      - empty set set()

    Returns a new dictionary with empty items removed.
    """
    if not isinstance(d, dict):
        raise TypeError("Input must be a dictionary")

    def is_empty(value):
        if value is None:
            return True
        if isinstance(value, (str, list, dict, tuple, set)) and len(value) == 0:
            return True
        return False

    def clean(value):
        if isinstance(value, dict):
            cleaned_dict = {k: clean(v) for k, v in value.items()}
            # Remove empty items from cleaned_dict
            return {k: v for k, v in cleaned_dict.items() if not is_empty(v)}
        elif isinstance(value, list):
            cleaned_list = [clean(v) for v in value]
            return [v for v in cleaned_list if not is_empty(v)]
        elif isinstance(value, tuple):
            cleaned_tuple = tuple(clean(v) for v in value)
            return tuple(v for v in cleaned_tuple if not is_empty(v))
        elif isinstance(value, set):
            cleaned_set = {clean(v) for v in value}
            return {v for v in cleaned_set if not is_empty(v)}
        else:
            return value

    cleaned = clean(d)
    # Finally remove empty items at top-level dict
    return {k: v for k, v in cleaned.items() if not is_empty(v)}


