def filter_data(data, min_height=None, max_height=None, min_width=None, max_width=None):
    """
    Filters students by height and width criteria.

    Parameters:
    - data: dict, where keys are student names and values are dicts with 'height' and 'width' keys.
    - min_height: float or int, minimum height inclusive (if None, no minimum)
    - max_height: float or int, maximum height inclusive (if None, no maximum)
    - min_width: float or int, minimum width inclusive (if None, no minimum)
    - max_width: float or int, maximum width inclusive (if None, no maximum)

    Returns:
    - filtered_data: dict containing only students that meet all provided criteria.
    """
    filtered_data = {}

    for student, measurements in data.items():
        height = measurements.get('height')
        width = measurements.get('width')

        if height is None or width is None:
            continue  # skip if any measurement is missing

        if min_height is not None and height < min_height:
            continue
        if max_height is not None and height > max_height:
            continue
        if min_width is not None and width < min_width:
            continue
        if max_width is not None and width > max_width:
            continue

        filtered_data[student] = measurements

    return filtered_data


# Example usage:
if __name__ == "__main__":
    students = {
        "Alice": {"height": 160, "width": 50},
        "Bob": {"height": 170, "width": 60},
        "Charlie": {"height": 165, "width": 55},
        "Diana": {"height": 155, "width": 48},
    }

    # Filter students with height between 160 and 170 and width between 50 and 60
    filtered_students = filter_data(students, min_height=160, max_height=170, min_width=50, max_width=60)
    print(filtered_students)
    # Expected output: {'Alice': {'height': 160, 'width': 50}, 'Bob': {'height': 170, 'width': 60}, 'Charlie': {'height': 165, 'width': 55}}

def lcm(a, b):
    """Return the least common multiple of two positive integers a and b."""
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    return a * b // gcd(a, b)


# Example usage:
if __name__ == "__main__":
    print(lcm(12, 18))  # Output: 36
    print(lcm(7, 5))    # Output: 35

