def Find_Min_Length(list_of_lists):
    """
    Returns the length of the shortest sublist within the given list of lists.

    Parameters:
    list_of_lists (list of lists): The input list containing sublists.

    Returns:
    int: The length of the shortest sublist. Returns 0 if the input list is empty.

    Raises:
    ValueError: If any element in list_of_lists is not a list.
    """
    if not list_of_lists:
        return 0

    for sublist in list_of_lists:
        if not isinstance(sublist, list):
            raise ValueError("All elements of the input must be lists.")

    return min(len(sublist) for sublist in list_of_lists)


