def next_smallest_palindrome(num: int) -> int:
    """
    Given an integer num, find the smallest palindrome strictly greater than num.
    Returns the palindrome as an integer.
    """
    def is_all_nines(n_str):
        return all(ch == '9' for ch in n_str)

    def make_palindrome(left, odd_length):
        # Construct palindrome from left half and middle (if odd length)
        if odd_length:
            return left + left[:-1][::-1]
        else:
            return left + left[::-1]

    s = str(num)
    length = len(s)

    # If all digits are 9, the next palindrome is 10...01 (length+1)
    if is_all_nines(s):
        return int('1' + ('0' * (length -1)) + '1')

    # Increment num by 1 to find strictly greater palindrome
    num += 1
    s = str(num)
    length = len(s)
    odd = (length % 2 != 0)

    # Split into left and right parts
    if odd:
        left = s[:length // 2 + 1]
        palindrome = make_palindrome(left, True)
    else:
        left = s[:length // 2]
        palindrome = make_palindrome(left, False)

    if int(palindrome) >= num:
        return int(palindrome)

    # If palindrome <= num, we need to increment the middle part and form palindrome again
    if odd:
        # Increment left half (including middle)
        left_int = int(left)
        left_int += 1
        left = str(left_int)
        # If length of left changed (e.g. 999 + 1 = 1000), adjust accordingly
        if len(left) > (length // 2 + 1):
            # This means number length increased by 1, form palindrome accordingly
            # For example: 999 -> 1000 is length 4, so now even length palindrome
            if length % 2 == 1:
                # Now length is even
                palindrome = make_palindrome(left, False)
            else:
                palindrome = make_palindrome(left, False)
        else:
            palindrome = make_palindrome(left, True)
    else:
        # Even length number, increment left half
        left_int = int(left)
        left_int += 1
        left = str(left_int)
        if len(left) > (length // 2):
            # Length increased, e.g. 99 -> 100, so next palindrome length increases by 1
            # The next palindrome is 10...01 with length+1
            return int('1' + ('0' * (length - 1)) + '1')
        palindrome = make_palindrome(left, False)

    return int(palindrome)


