    permute_string("aabc")

def filter_data(data, min_height=None, max_height=None, min_width=None, max_width=None):
    """
    Filters students based on height and width constraints.

    Parameters:
    - data (dict): Dictionary with student names as keys and a dict with 'height' and 'width' as values.
                   Example: {'Alice': {'height': 160, 'width': 50}, ...}
    - min_height (float or int, optional): Minimum height to include.
    - max_height (float or int, optional): Maximum height to include.
    - min_width (float or int, optional): Minimum width to include.
    - max_width (float or int, optional): Maximum width to include.

    Returns:
    - dict: Filtered dictionary with students meeting the criteria.
    """
    filtered = {}
    for student, measurements in data.items():
        height = measurements.get('height')
        width = measurements.get('width')

        if height is None or width is None:
            continue  # skip if data is incomplete

        if min_height is not None and height < min_height:
            continue
        if max_height is not None and height > max_height:
            continue
        if min_width is not None and width < min_width:
            continue
        if max_width is not None and width > max_width:
            continue

        filtered[student] = measurements

    return filtered


# Example usage:
if __name__ == "__main__":
    students = {
        'Alice': {'height': 160, 'width': 50},
        'Bob': {'height': 170, 'width': 55},
        'Charlie': {'height': 165, 'width': 52},
        'Diana': {'height': 158, 'width': 48}
    }

    # Filter students with height between 160 and 170 and width between 50 and 55
    result = filter_data(students, min_height=160, max_height=170, min_width=50, max_width=55)
    print(result)
